package org.apache.commons.math.fraction;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.MathIllegalArgumentException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.ZeroException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.ArithmeticUtils;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class BigFraction_floatValue_TriageGen1Test {

    private static final float EPSILON = 1e-7f;

    @Test
    public void testFloatValue_SimpleFraction() {
        // 1/2 = 0.5f
        BigFraction fraction = new BigFraction(1, 2);
        assertEquals(0.5f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_IntegerNumerator() {
        // 4/1 = 4.0f
        BigFraction fraction = new BigFraction(4, 1);
        assertEquals(4.0f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_LargeValues() {
        // Testing values that fit in float but are large BigIntegers
        BigInteger num = new BigInteger("1000000");
        BigInteger den = new BigInteger("3");
        BigFraction fraction = new BigFraction(num, den);
        assertEquals(333333.3333333333f, fraction.floatValue(), 1e-1f);
    }

    @Test
    public void testFloatValue_ZeroNumerator() {
        // 0/5 = 0.0f
        BigFraction fraction = new BigFraction(0, 5);
        assertEquals(0.0f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_NegativeFraction() {
        // -1/4 = -0.25f
        BigFraction fraction = new BigFraction(-1, 4);
        assertEquals(-0.25f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_NegativeDenominator() {
        // 1/-4 = -0.25f
        BigFraction fraction = new BigFraction(1, -4);
        assertEquals(-0.25f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_BothNegative() {
        // -1/-2 = 0.5f
        BigFraction fraction = new BigFraction(-1, -2);
        assertEquals(0.5f, fraction.floatValue(), EPSILON);
    }

    @Test
    public void testFloatValue_OverflowToInfinity() {
        // Very large numerator / 1 should result in Float.POSITIVE_INFINITY
        // Float.MAX_VALUE is approx 3.4e38
        BigInteger hugeNum = new BigInteger("1" + "0".repeat(40)); 
        BigFraction fraction = new BigFraction(hugeNum, BigInteger.ONE);
        assertEquals(Float.POSITIVE_INFINITY, fraction.floatValue(), 0.0f);
    }

    @Test
    public void testFloatValue_UnderflowToZero() {
        // Very small fraction should result in 0.0f
        // 1 / 10^40
        BigInteger hugeDen = new BigInteger("1" + "0".repeat(40));
        BigFraction fraction = new BigFraction(BigInteger.ONE, hugeDen);
        assertEquals(0.0f, fraction.floatValue(), 0.0f);
    }

    @Test
    public void testFloatValue_PrecisionLoss() {
        // BigFraction can represent numbers more precisely than float
        // 1/3 is 0.333...
        BigFraction fraction = new BigFraction(1, 3);
        float val = fraction.floatValue();
        // Verify it's close to 1/3
        assertEquals(0.33333334f, val, EPSILON);
    }
}
